package ttviet.dao; import java.sql.*;import javax.swing.table.DefaultTableModel; public class ProductDAO { public static DefaultTableModel load(){DefaultTableModel m=new DefaultTableModel(new String[]{"Mã","Tên món","Nhóm","Giá (VNĐ)"},0);String q="SELECT p.id,p.name,c.name,p.price FROM products p JOIN categories c ON p.category_id=c.id WHERE p.active=1 ORDER BY p.id";try(Connection c=DB.getConnection();Statement s=c.createStatement();ResultSet r=s.executeQuery(q)){while(r.next())m.addRow(new Object[]{r.getInt(1),r.getString(2),r.getString(3),r.getBigDecimal(4)});}catch(SQLException e){javax.swing.JOptionPane.showMessageDialog(null,e.getMessage());}return m;} }